BEGIN READ ONLY;
SELECT now() AS captured_at, current_setting('transaction_read_only') AS read_only, (SELECT count(*) FROM public.image_library) AS catalogue_rows, (SELECT count(DISTINCT code) FROM public.image_library) AS distinct_skus, (SELECT count(*) FROM public.catalogue_image_vectors) AS vector_rows, (SELECT count(*) FROM public.catalogue_image_vectors WHERE is_active) AS active_vectors, (SELECT jsonb_agg(x) FROM (SELECT asset_type,view_variant,embedding_model,embedding_model_version,preprocess_version,embedding_profile,is_active,count(*) AS rows FROM public.catalogue_image_vectors GROUP BY 1,2,3,4,5,6,7 ORDER BY 1,2) x) AS vector_groups, (SELECT jsonb_agg(x) FROM (SELECT view_mode,count(*) AS rows FROM public.image_library GROUP BY 1 ORDER BY 1) x) AS catalogue_views;
COMMIT;
